(7080, 'settings', 742, 'fa', NULL, NULL, 'کاربر موظف است اطلاعات صحیح وارد کند و مسئولیت حفظ محرمانگی رمز عبور بر عهده خود اوست. هرگونه فعالیت انجام‌شده با حساب کاربری به نام همان کاربر محسوب می‌شود.', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7081, 'settings', 733, 'fa', NULL, NULL, '۳. محتوای آموزشی', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7082, 'settings', 743, 'fa', NULL, NULL, 'محتوای دوره‌ها، مقالات و فایل‌های آموزشی صرفاً برای استفاده شخصی هنرجو است و انتشار، فروش یا کپی‌برداری بدون مجوز کتبی ممنوع است.', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7083, 'settings', 734, 'fa', NULL, NULL, '۴. پرداخت و انصراف', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7084, 'settings', 744, 'fa', NULL, NULL, 'شهریه دوره‌ها طبق تعرفه‌های اعلام‌شده دریافت می‌شود. شرایط استرداد وجه مطابق آیین‌نامه مالی آموزشگاه خواهد بود.', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7085, 'settings', 735, 'fa', NULL, NULL, '۵. حریم خصوصی', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7086, 'settings', 745, 'fa', NULL, NULL, 'اطلاعات شخصی کاربران محرمانه نگهداری می‌شود و جز در موارد قانونی یا با رضایت کاربر در اختیار شخص ثالث قرار نمی‌گیرد.', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7087, 'settings', 736, 'fa', NULL, NULL, '۶. رفتار کاربران', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
(7088, 'settings', 746, 'fa', NULL, NULL, 'هرگونه محتوای توهین‌آمیز، اسپم یا نقض حقوق دیگران در پیام‌ها، نظرات و پروفایل ممنوع است و می‌تواند به تعلیق حساب منجر شود.', NULL, '2026-08-06 14:57:25', NULL, '2026-08-06 14:57:25', NULL, NULL, NULL, NULL, NULL),
